fn hstack(a: Vec<f32>, b: Vec<f32>) -> Vec<f32> {
    // Pre-allocate enough space for all elements
    let mut result = Vec::with_capacity(a.len() + b.len());
    // Copy in all elements from `a`
    result.extend_from_slice(&a);
    // Then copy in all elements from `b`
    result.extend_from_slice(&b);
    result
}

